//! Ids, timestamps and the text rules of Python's `str` that stored values depend on.

use std::time::{SystemTime, UNIX_EPOCH};

use unicode_properties::{GeneralCategory, UnicodeGeneralCategory};

// One id rule for memories, projects and changes: 10 random lowercase Crockford
// base32 characters (50 bits), generated by the system and never proposed by a
// caller. The alphabet leaves out i, l, o and u so an id survives being read and
// retyped. Uniqueness is the stores' job: they refuse an id that is taken.
pub const ID_ALPHABET: &str = "0123456789abcdefghjkmnpqrstvwxyz";
pub const ID_LENGTH: usize = 10;

pub fn new_id() -> String {
    let mut raw = [0u8; ID_LENGTH];
    getrandom::fill(&mut raw).expect("the system's random source");
    // 256 is a multiple of 32, so the low five bits of a byte are uniform
    raw.iter()
        .map(|byte| ID_ALPHABET.as_bytes()[usize::from(byte & 31)] as char)
        .collect()
}

/// Whether `value` is exactly ten symbols of the id alphabet.
pub fn is_id(value: &str) -> bool {
    value.len() == ID_LENGTH
        && value
            .bytes()
            .all(|byte| ID_ALPHABET.as_bytes().contains(&byte))
}

/// Python's `str.isspace()` for one character: White_Space plus U+001C..U+001F.
pub fn py_isspace(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Python's `str.isprintable()` for one character: a space, or anything that is not a
/// control, format, private-use or unassigned character and not a separator.
pub fn py_isprintable(c: char) -> bool {
    c == ' '
        || !matches!(
            c.general_category(),
            GeneralCategory::Control
                | GeneralCategory::Format
                | GeneralCategory::Surrogate
                | GeneralCategory::PrivateUse
                | GeneralCategory::Unassigned
                | GeneralCategory::LineSeparator
                | GeneralCategory::ParagraphSeparator
                | GeneralCategory::SpaceSeparator
        )
}

/// Python's `str.strip()`.
pub fn py_strip(value: &str) -> &str {
    value.trim_matches(py_isspace)
}

/// Python's `str.split()`: the runs between whitespace, none of them empty.
pub fn py_split(value: &str) -> impl Iterator<Item = &str> {
    value.split(py_isspace).filter(|piece| !piece.is_empty())
}

/// The first `scalars` characters of `value` (Python's `value[:scalars]`).
pub fn cut(value: &str, scalars: usize) -> &str {
    match value.char_indices().nth(scalars) {
        Some((end, _)) => &value[..end],
        None => value,
    }
}

/// Python's `os.path.normpath` for a POSIX path: empty parts and `.` dropped, `..`
/// resolved by the text alone, exactly two leading slashes kept.
pub fn py_normpath(path: &[u8]) -> Vec<u8> {
    let slashes = match path {
        [b'/', b'/', b'/', ..] => 1,
        [b'/', b'/', ..] => 2,
        [b'/', ..] => 1,
        _ => 0,
    };
    let mut kept: Vec<&[u8]> = Vec::new();
    for part in path.split(|byte| *byte == b'/') {
        match part {
            b"" | b"." => {}
            b".." if kept.last().is_some_and(|last| *last != b"..") => {
                kept.pop();
            }
            // above the root there is only the root
            b".." if slashes > 0 && kept.is_empty() => {}
            _ => kept.push(part),
        }
    }
    let normal = [vec![b'/'; slashes], kept.join(&b'/')].concat();
    if normal.is_empty() {
        b".".to_vec()
    } else {
        normal
    }
}

/// Python's `repr()` of a string: quoted, with the quote that needs no escape, and
/// everything that is not printable written as an escape.
pub fn py_repr(value: &str) -> String {
    let quote = if value.contains('\'') && !value.contains('"') {
        '"'
    } else {
        '\''
    };
    let mut repr = String::from(quote);
    for c in value.chars() {
        match c {
            '\\' => repr.push_str("\\\\"),
            '\t' => repr.push_str("\\t"),
            '\n' => repr.push_str("\\n"),
            '\r' => repr.push_str("\\r"),
            c if c == quote => {
                repr.push('\\');
                repr.push(c);
            }
            ' '..='~' => repr.push(c),
            c if c.is_ascii() || !py_isprintable(c) => match c as u32 {
                code @ ..0x100 => repr.push_str(&format!("\\x{code:02x}")),
                code @ ..0x10000 => repr.push_str(&format!("\\u{code:04x}")),
                code => repr.push_str(&format!("\\U{code:08x}")),
            },
            c => repr.push(c),
        }
    }
    repr.push(quote);
    repr
}

/// `value` on one line: control characters and the Unicode line separators become
/// spaces, runs of whitespace collapse to one space and the ends are dropped. Stored
/// fields are injected into agent context line by line, so no field may carry a line
/// break into another line.
pub fn single_line(value: &str) -> String {
    let line_unsafe =
        |c: char| matches!(c, '\0'..='\u{1f}' | '\u{7f}'..='\u{9f}' | '\u{2028}' | '\u{2029}');
    let replaced: String = value
        .chars()
        .map(|c| if line_unsafe(c) { ' ' } else { c })
        .collect();
    py_split(&replaced).collect::<Vec<_>>().join(" ")
}

// --- timestamps: the fixed-width UTC form YYYY-MM-DDTHH:MM:SS.ffffffZ ---
//
// Two of them compare as text in chronological order; the stores rely on it.

fn days_from_civil(year: i64, month: i64, day: i64) -> i64 {
    let y = year - i64::from(month <= 2);
    let (era, yoe) = (y.div_euclid(400), y.rem_euclid(400));
    let doy = (153 * ((month + 9) % 12) + 2) / 5 + day - 1;
    era * 146_097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719_468
}

fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let (era, doe) = (z.div_euclid(146_097), z.rem_euclid(146_097));
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    (
        yoe + era * 400 + i64::from(month <= 2),
        month,
        doy - (153 * mp + 2) / 5 + 1,
    )
}

/// Microseconds since 1970 of a timestamp in the canonical form; None for anything
/// else, a date the calendar does not have included.
pub fn parse_timestamp(value: &str) -> Option<i64> {
    const SHAPE: &[u8] = b"dddd-dd-ddTdd:dd:dd.ddddddZ";
    let bytes = value.as_bytes();
    // ASCII digits only: full-width and other Unicode digits are not a timestamp
    let fits = |(byte, shape): (&u8, &u8)| match *shape {
        b'd' => byte.is_ascii_digit(),
        other => *byte == other,
    };
    if bytes.len() != SHAPE.len() || !bytes.iter().zip(SHAPE).all(fits) {
        return None;
    }
    let number = |from: usize, to: usize| value[from..to].parse::<i64>().ok();
    let (year, month, day) = (number(0, 4)?, number(5, 7)?, number(8, 10)?);
    let (hour, minute, second) = (number(11, 13)?, number(14, 16)?, number(17, 19)?);
    if year < 1 || hour > 23 || minute > 59 || second > 59 {
        return None;
    }
    let days = days_from_civil(year, month, day);
    if civil_from_days(days) != (year, month, day) {
        return None; // month 13, February 30 and the like
    }
    Some((days * 86_400 + hour * 3600 + minute * 60 + second) * 1_000_000 + number(20, 26)?)
}

/// The canonical form of `micros` since 1970; None outside the years 0001 to 9999,
/// which is all the fixed-width form can hold.
pub fn format_micros(micros: i64) -> Option<String> {
    let (seconds, fraction) = (micros.div_euclid(1_000_000), micros.rem_euclid(1_000_000));
    let (days, rest) = (seconds.div_euclid(86_400), seconds.rem_euclid(86_400));
    let (year, month, day) = civil_from_days(days);
    (1..=9999).contains(&year).then(|| {
        format!(
            "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}.{fraction:06}Z",
            rest / 3600,
            rest % 3600 / 60,
            rest % 60
        )
    })
}

/// Whether `value` is exactly the fixed-width UTC form `now()` produces.
pub fn is_timestamp(value: &str) -> bool {
    parse_timestamp(value).is_some()
}

/// The current time. Microseconds, not seconds: `updated` is the recency sort key,
/// and a same-second update must still advance it.
pub fn now() -> String {
    let micros = match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(since) => i64::try_from(since.as_micros()).ok(),
        Err(before) => i64::try_from(before.duration().as_micros())
            .ok()
            .map(|micros| -micros),
    };
    micros
        .and_then(format_micros)
        .expect("a clock between the years 0001 and 9999")
}

/// `now()`, forced past `previous` when the clock has not moved on: the clock's tick
/// can be coarser than two consecutive writes, and it can step backwards. A
/// `previous` outside the canonical form carries no comparable instant, and neither
/// does one with no later instant in the form; there the clock reading is all there is.
pub fn now_strictly_after(previous: &str) -> String {
    strictly_after(now(), previous)
}

fn strictly_after(stamp: String, previous: &str) -> String {
    match parse_timestamp(previous).and_then(|micros| format_micros(micros + 1)) {
        // both are the same fixed-width form, so text order is chronological
        Some(earliest) => stamp.max(earliest),
        None => stamp,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn repr_is_pythons() {
        // expectations taken from Python's repr()
        for (value, repr) in [
            ("/a/b", "'/a/b'"),
            ("/it's", "\"/it's\""),
            ("/q\"x'", "'/q\"x\\''"),
            ("/tab\there", "'/tab\\there'"),
            ("/\u{e9}/\u{9805}", "'/\u{e9}/\u{9805}'"),
            ("/x\u{7f}\u{1}", "'/x\\x7f\\x01'"),
            ("/nl\n", "'/nl\\n'"),
            ("/\u{2028}z", "'/\\u2028z'"),
            ("/b\\s", "'/b\\\\s'"),
            ("/\u{1f600}", "'/\u{1f600}'"),
            ("/\u{a0}", "'/\\xa0'"),
            ("/\u{ad}", "'/\\xad'"),
            ("/\u{e0001}", "'/\\U000e0001'"),
        ] {
            assert_eq!(py_repr(value), repr, "{value:?}");
        }
    }

    #[test]
    fn normpath_is_pythons() {
        // expectations taken from Python's os.path.normpath
        for (path, normal) in [
            ("", "."),
            ("/", "/"),
            ("//", "//"),
            ("///", "/"),
            ("/a/b/../c/", "/a/c"),
            ("a/./b", "a/b"),
            ("..", ".."),
            ("../..", "../.."),
            ("/..", "/"),
            ("//..", "//"),
            ("a/..", "."),
            ("a/../..", ".."),
            ("/a//b", "/a/b"),
            ("//a//b/", "//a/b"),
            ("///a", "/a"),
            ("./a", "a"),
            ("/work/x/../a", "/work/a"),
            ("/.../a", "/.../a"),
            ("/a/..b", "/a/..b"),
            ("a/b/../../../c", "../c"),
        ] {
            assert_eq!(py_normpath(path.as_bytes()), normal.as_bytes(), "{path:?}");
        }
        // bytes, not text: a name that is not UTF-8 passes through
        assert_eq!(py_normpath(b"/a/\xff/./b"), b"/a/\xff/b");
    }

    #[test]
    fn new_id_uses_the_alphabet() {
        assert_eq!(ID_ALPHABET, "0123456789abcdefghjkmnpqrstvwxyz");
        assert_eq!(ID_LENGTH, 10);
        let generated: Vec<String> = (0..500).map(|_| new_id()).collect();
        assert!(generated.iter().all(|id| is_id(id)));
        // 500 draws of 50 bits: a repeat would be a broken generator, not luck
        let distinct: std::collections::HashSet<&String> = generated.iter().collect();
        assert_eq!(distinct.len(), 500);
        // every symbol turns up in 5,000 draws unless some are never chosen
        let seen: std::collections::HashSet<char> = generated.concat().chars().collect();
        assert_eq!(seen.len(), 32);
        assert!(is_id("0123456789") && is_id("zzzzzzzzzz"));
        for bad in [
            "AAAAAAAAAA",
            "aaaaaaaaa",
            "aaaaaaaaaaa",
            "aaaaaaaaai",
            "aaaaaaaaal",
            "aaaaaaaaao",
            "aaaaaaaaau",
            "aaaa-aaaaa",
            "01ARZ3NDEKTSV4RRFFQ69G5FAV",
            "",
            "aaaaaaaa\u{e9}",
            "aaaaaaaaa\n",
        ] {
            assert!(!is_id(bad), "{bad:?}");
        }
    }

    #[test]
    fn timestamp_is_27_chars_utc() {
        let (first, second) = (now(), now());
        assert_eq!(first.len(), 27);
        assert!(is_timestamp(&first), "{first}");
        assert!(first <= second);
        assert_eq!(
            format_micros(0).as_deref(),
            Some("1970-01-01T00:00:00.000000Z")
        );
        assert_eq!(
            format_micros(1_795_313_803_300_060).as_deref(),
            Some("2026-11-22T02:16:43.300060Z")
        );
        // before the epoch, and the two ends of what the form can hold
        assert_eq!(
            format_micros(-1).as_deref(),
            Some("1969-12-31T23:59:59.999999Z")
        );
        let first_instant = parse_timestamp("0001-01-01T00:00:00.000000Z").unwrap();
        let last_instant = parse_timestamp("9999-12-31T23:59:59.999999Z").unwrap();
        assert_eq!(
            format_micros(first_instant).as_deref(),
            Some("0001-01-01T00:00:00.000000Z")
        );
        assert_eq!(
            format_micros(last_instant).as_deref(),
            Some("9999-12-31T23:59:59.999999Z")
        );
        assert_eq!(format_micros(first_instant - 1), None);
        assert_eq!(format_micros(last_instant + 1), None);
    }

    #[test]
    fn is_timestamp_rejects_month_13_and_fullwidth_digits() {
        for good in [
            "2026-11-22T02:16:43.300060Z",
            "2024-02-29T00:00:00.000000Z",
            "2000-02-29T00:00:00.000000Z",
            "0001-01-01T00:00:00.000000Z",
            "9999-12-31T23:59:59.999999Z",
        ] {
            assert!(is_timestamp(good), "{good}");
        }
        for bad in [
            "2026-13-01T00:00:00.000000Z",
            "2026-00-10T00:00:00.000000Z",
            "2026-02-30T00:00:00.000000Z",
            "2023-02-29T00:00:00.000000Z",
            "1900-02-29T00:00:00.000000Z",
            "2026-04-31T00:00:00.000000Z",
            "2026-11-00T00:00:00.000000Z",
            "0000-01-01T00:00:00.000000Z",
            "2026-12-31T23:59:60.000000Z",
            "2026-12-31T23:59:61.000000Z",
            "2026-12-31T24:00:00.000000Z",
            "2026-12-31T23:60:00.000000Z",
            "2026-11-22T02:16:43.30006Z",
            "\u{ff12}\u{ff10}\u{ff12}\u{ff16}-11-22T02:16:43.300060Z",
            "2026-11-22T02:16:43.300060Z\n",
            "2026-11-22 02:16:43.300060Z",
            "2026-11-22T02:16:43.300060z",
            "",
            "yesterday",
        ] {
            assert!(!is_timestamp(bad), "{bad:?}");
        }
    }

    #[test]
    fn now_strictly_after_moves_one_microsecond() {
        // the clock stands still, or is behind the stored time
        let frozen = "2026-09-23T00:00:00.000000Z";
        assert_eq!(
            strictly_after(frozen.to_string(), frozen),
            "2026-09-23T00:00:00.000001Z"
        );
        assert_eq!(
            strictly_after(frozen.to_string(), "2026-09-24T00:00:00.000000Z"),
            "2026-09-24T00:00:00.000001Z"
        );
        // carries through every field
        assert_eq!(
            strictly_after(frozen.to_string(), "2026-12-31T23:59:59.999999Z"),
            "2027-01-01T00:00:00.000000Z"
        );
        // the clock has moved on: the clock wins
        assert_eq!(
            strictly_after(frozen.to_string(), "2026-09-22T23:59:59.999999Z"),
            frozen
        );
        let later = now_strictly_after("9999-01-01T00:00:00.000000Z");
        assert_eq!(later, "9999-01-01T00:00:00.000001Z");
    }

    #[test]
    fn now_strictly_after_falls_back_to_the_clock_for_a_non_canonical_value() {
        assert!(is_timestamp(&now_strictly_after("yesterday")));
        let frozen = "2026-09-23T00:00:00.000000Z";
        assert_eq!(
            strictly_after(frozen.to_string(), "2026-02-30T00:00:00.000000Z"),
            frozen
        );
        // one microsecond past the last instant the form can hold
        assert_eq!(
            strictly_after(frozen.to_string(), "9999-12-31T23:59:59.999999Z"),
            frozen
        );
        // a later time in any other spelling is not compared either: short fields, a
        // short fraction, lower-case letters, digits outside ASCII
        for loose in [
            "2199-1-1T0:0:0.5Z",
            "2199-01-01T00:00:00.5Z",
            "2199-01-01t00:00:00.000000z",
            "\u{ff12}\u{ff11}\u{ff19}\u{ff19}-01-01T00:00:00.000000Z",
        ] {
            assert_eq!(
                strictly_after(frozen.to_string(), loose),
                frozen,
                "{loose:?}"
            );
        }
    }

    #[test]
    fn single_line_collapses_controls_and_u2028() {
        assert_eq!(single_line("a\nb c\0d   e\u{2028}f"), "a b c d e f");
        assert_eq!(
            single_line(" a\n\tb\u{2028}c  d\u{1f}\u{85}e\u{a0}f\u{3000}g\u{7f}h\u{9f}i "),
            "a b c d e f g h i"
        );
        assert_eq!(single_line(""), "");
        assert_eq!(single_line(" \u{2029}\r\n"), "");
        // a format character is not a line break and stays
        assert_eq!(single_line("a\u{200b}b"), "a\u{200b}b");
    }

    #[test]
    fn py_strip_removes_u001f_where_trim_does_not() {
        assert_eq!(py_strip("\u{1f} x \u{1c}"), "x");
        assert_eq!("\u{1f} x \u{1c}".trim(), "\u{1f} x \u{1c}");
        assert_eq!(
            py_strip("\u{1c}\u{1d}\u{1e}\u{1f}\u{3000}\u{a0}\u{85}body\t\n"),
            "body"
        );
        assert_eq!(py_strip(" \u{1f} "), "");
        // not whitespace to Python: the zero-width space and the byte order mark
        assert_eq!(py_strip("\u{200b}x\u{feff}"), "\u{200b}x\u{feff}");
        assert_eq!(
            py_split("\u{1f}a\u{1e}\u{3000}b c\n").collect::<Vec<_>>(),
            ["a", "b", "c"]
        );
        assert_eq!(py_split(" \u{1c} ").count(), 0);
    }

    #[test]
    fn limits_count_scalars_not_bytes() {
        let cue = "\u{8bb0}".repeat(61);
        assert_eq!(cut(&cue, 60).chars().count(), 60);
        assert_eq!(cut(&cue, 60).len(), 180);
        assert_eq!(cut("\u{65e5}\u{672c}\u{8a9e}", 2), "\u{65e5}\u{672c}");
        // a character outside the BMP is one scalar, and is never cut in two
        assert_eq!(cut("a\u{1f600}b", 2), "a\u{1f600}");
        // a base letter and its combining mark are two
        assert_eq!(cut("e\u{301}x", 1), "e");
        assert_eq!(cut("abc", 3), "abc");
        assert_eq!(cut("abc", 9), "abc");
        assert_eq!(cut("abc", 0), "");
        // a prompt of 512 characters of four bytes each, and one more
        let prompt = format!("{}x", "\u{1f600}".repeat(512));
        assert_eq!(cut(&prompt, 512).len(), 2048);
        assert_eq!(cut(&prompt, 512).chars().count(), 512);
        assert_eq!(cut(&prompt, 513), prompt);
    }

    #[test]
    fn the_whitespace_of_python_is_these_29_characters() {
        let expected: Vec<u32> = (0x09..=0x0d)
            .chain(0x1c..=0x20)
            .chain([0x85, 0xa0, 0x1680])
            .chain(0x2000..=0x200a)
            .chain([0x2028, 0x2029, 0x202f, 0x205f, 0x3000])
            .collect();
        assert_eq!(expected.len(), 29);
        let found: Vec<u32> = (0..=u32::from(char::MAX))
            .filter(|code| char::from_u32(*code).is_some_and(py_isspace))
            .collect();
        assert_eq!(found, expected);
    }

    #[test]
    fn the_unicode_tables_are_the_measured_version() {
        // the fold and the printable test were compared with Python on these tables;
        // other tables mean other answers, to be measured again
        assert_eq!(unicode_properties::UNICODE_VERSION, (18, 0, 0));
        assert_eq!(unicode_normalization::UNICODE_VERSION, (18, 0, 0));
        assert_eq!(caseless::UNICODE_VERSION, (16, 0, 0));
    }

    #[test]
    fn printable_and_space_follow_python() {
        for c in ['a', ' ', '\u{4f1a}', '\u{1f600}', '\u{e9}', '\u{301}', '~'] {
            assert!(py_isprintable(c), "{c:?}");
        }
        for c in [
            '\0',
            '\t',
            '\n',
            '\u{1f}',
            '\u{7f}',
            '\u{85}',
            '\u{a0}',
            '\u{ad}',
            '\u{200b}',
            '\u{202e}',
            '\u{2028}',
            '\u{2029}',
            '\u{3000}',
            '\u{e000}',
            '\u{feff}',
            '\u{378}',
            '\u{10ffff}',
        ] {
            assert!(!py_isprintable(c), "{c:?}");
        }
        for c in [
            '\t', '\n', '\u{b}', '\u{c}', '\r', '\u{1c}', '\u{1d}', '\u{1e}', '\u{1f}', ' ',
            '\u{85}', '\u{a0}', '\u{1680}', '\u{2000}', '\u{200a}', '\u{2028}', '\u{2029}',
            '\u{202f}', '\u{205f}', '\u{3000}',
        ] {
            assert!(py_isspace(c), "{c:?}");
        }
        for c in [
            'a', '\0', '\u{1b}', '\u{200b}', '\u{feff}', '\u{180e}', '\u{2060}',
        ] {
            assert!(!py_isspace(c), "{c:?}");
        }
    }
}
